BEGIN;
SET LOCAL standard_conforming_strings = on;
DO $activity_guard$ BEGIN IF (SELECT count(*) FROM tiago_lab.establishment) <> 5261 OR EXISTS (SELECT 1 FROM tiago_lab.person) OR EXISTS (SELECT 1 FROM tiago_lab.reservation) OR EXISTS (SELECT 1 FROM tiago_lab.visit) THEN RAISE EXCEPTION 'Catalogo inesperado ou atividade ja existente' USING ERRCODE = 'P0001'; END IF; END $activity_guard$;
COMMIT;
